.init-table{
    display: flex;
    flex-direction: column;
    margin: 20px;
    margin-top: 30px;
    width: 100%;
}

.init-table .row{
    display: flex;
    width: 100%;
    justify-content: center;
}

.init-table .row .column{
    display: flex;
    flex-direction: column;
}

.init-table .text{
	font-family: "Game Of Squids";
    text-decoration: none;
    color: white;
}


.init-table a{
	display: flex;
    flex-direction: column;
    align-items: center;
    padding-bottom: 30px;
    padding-right: 15px;
    padding-left: 15px;
    border-radius: 10px;
}

.init-table a:hover{
	border: 2px solid #ff00b2;
